const EXPECTED={lines:15,oxymorons:10,stories:20,history:15,gods:10,qualities:10,works:20};
const TOPIC_TO_CAT=Object.fromEntries(Object.entries(CATS).map(([k,v])=>[v,k]));
const STORAGE_KEY="greeklit-study-hub-v1";
const freshState=()=>({answered:{},mistakes:[],scores:[],flashcards:{},settings:{difficulty:"Any"},streak:0,lastStudy:null});
function loadState(){try{return {...freshState(),...JSON.parse(localStorage.getItem(STORAGE_KEY)||"{}")}}catch{return freshState()}}
