function applyTheme(){const dark=state.settings?.theme==="dark";document.documentElement.dataset.theme=dark?"dark":"light";const toggle=document.querySelector(".theme-toggle");if(toggle){toggle.textContent=dark?"☀":"☾";toggle.title=dark?"Switch to light mode":"Switch to dark mode";toggle.setAttribute("aria-label",toggle.title)}const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=dark?"#1b1d1e":"#f6f3ec"}
function toggleTheme(){state.settings??={};state.settings.theme=state.settings.theme==="dark"?"light":"dark";saveState();applyTheme();if(activePage==="settings")renderSettings()}
function shuffled(items){const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function pct(a,b){return b?Math.round(a/b*100):0}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function categoryFor(q){return TOPIC_TO_CAT[q.category]||"works"}
function performance(){const map={};for(const key of Object.keys(CATS)){const qs=qbank.filter(q=>categoryFor(q)===key),done=qs.filter(q=>state.answered[q.id]),right=done.filter(q=>state.answered[q.id]===true).length;map[key]={total:qs.length,done:done.length,right,accuracy:pct(right,done.length),remaining:qs.length-done.length}}return map}
function weakestTopic(){const p=performance();return Object.entries(p).filter(([,v])=>v.done).sort((a,b)=>a[1].accuracy-b[1].accuracy)[0]}
function topicsProgress(){return Object.entries(CATS).map(([key,title])=>{const p=performance()[key];return `<div class="topic-card" data-topic="${key}"><div class="topic-top"><div class="topic-icon">${topicIcon(key)}</div><div><div class="topic-name">${title}</div><div class="topic-sub">${p.done} of ${p.total} practiced</div></div><div class="topic-score">${p.done?p.accuracy+"%":"—"}</div></div><div class="progress-track"><div class="progress-fill" style="width:${p.total?p.done/p.total*100:0}%"></div></div><div class="topic-foot"><span>${p.done?`${p.right} correct`:"Not started"}</span><span>${p.remaining} remaining</span></div></div>`}).join("")}
