function renderDashboard(){const s=totalStats(),weak=weakestTopic(),recommend=weak?`<div class="recommend"><span class="recommend-icon">◎</span><div><b>${CATS[weak[0]]} could use a little practice</b><p>Your accuracy here is ${weak[1].accuracy}%. A short focused set can help strengthen recall.</p><button class="text-link" data-action="practice-topic" data-topic="${weak[0]}">Practice this topic →</button></div></div>`:`<div class="recommend"><span class="recommend-icon">✦</span><div><b>Your review plan starts here</b><p>Try a short practice set. We’ll recommend a topic based on the questions you find tricky.</p><button class="text-link" data-page="practice">Start a practice set →</button></div></div>`;const recent=state.scores.slice(-3).reverse();pageContent.innerHTML=`<div class="welcome-row"><div><div class="eyebrow">A LITTLE PRACTICE GOES A LONG WAY</div><h1 class="page-title">Good ${greeting()}, ready to learn?</h1><p class="subtitle">Build confidence for your Literature exam, one question at a time.</p><div class="pattern"></div></div><button class="primary-btn" data-page="practice">Start practicing <span class="btn-arrow">→</span></button></div><div class="stats-grid"><div class="stat-card"><div class="stat-top">Questions answered <span class="stat-icon">◉</span></div><div class="stat-value">${s.done}</div><div class="stat-foot">of 100 in the question bank</div></div><div class="stat-card"><div class="stat-top">Correct answers <span class="stat-icon">✓</span></div><div class="stat-value">${s.right}</div><div class="stat-foot">Keep your recall sharp</div></div><div class="stat-card"><div class="stat-top">Overall accuracy <span class="stat-icon">↗</span></div><div class="stat-value">${s.accuracy}%</div><div class="stat-foot">Across questions you've answered</div></div><div class="stat-card"><div class="stat-top">Saved mistakes <span class="stat-icon">↻</span></div><div class="stat-value">${state.mistakes.length}</div><div class="stat-foot">Ready for another review</div></div></div><div class="section-head"><h2>Your study topics</h2><button class="text-link" data-page="topics">View all topics →</button></div><div class="topic-grid">${topicsProgress()}</div><div class="dashboard-lower"><section class="panel"><h3>What should I study?</h3>${recommend}</section><section class="panel"><h3>Recent practice</h3>${recent.length?recent.map(r=>`<div class="recent-row"><span>${esc(r.label)} · ${new Date(r.date).toLocaleDateString()}</span><span class="score-pill">${r.score}/${r.total}</span></div>`).join(""):`<div class="recent-empty">Your quiz scores will show here after your first practice.</div>`}</section></div>`}
function greeting(){const h=new Date().getHours();return h<12?"morning":h<18?"afternoon":"evening"}
function renderTopics(){pageContent.innerHTML=`<div class="eyebrow">YOUR EXAM, ORGANIZED</div><h1 class="page-title">Study topics</h1><p class="subtitle">Choose a section to practice its questions or browse a quick reference.</p><div class="section-head"><h2>All 7 exam sections <span class="small">· exactly 100 questions</span></h2></div><div class="topic-grid">${topicsProgress()}</div><div class="section-head"><h2>Greek gods quick reference</h2><span class="small">Domains and familiar symbols</span></div><div class="god-grid">${godReference()}</div>`}
function godReference(){return [["Zeus","Sky, thunder, kingship · thunderbolt","Brother of Poseidon and Hades."],["Hera","Marriage and queenship · peacock","Wife and sister of Zeus."],["Poseidon","Sea, earthquakes · trident","Brother of Zeus; father of Polyphemus in the Odyssey."],["Athena","Wisdom, strategy · owl","Daughter of Zeus; helper of Odysseus."],["Apollo","Music, prophecy · lyre","Son of Zeus; twin of Artemis."],["Artemis","Hunt and wilderness · bow","Daughter of Zeus; twin of Apollo."],["Aphrodite","Love and beauty · dove","Goddess associated with desire and attraction."],["Hermes","Messages and travel · winged sandals","Son of Zeus and Maia; messenger of the gods."],["Ares","War · spear","Son of Zeus and Hera in common traditions."],["Demeter","Harvest and grain · sheaf","Mother of Persephone."],["Hephaestus","Fire and metalwork · hammer","Divine smith, commonly said to be Hera's son."],["Dionysus","Wine and theater · ivy","God honored at festivals where drama developed."]].map(x=>`<div class="god-card"><b>${x[0]}</b><p>${x[1]}<br>${x[2]}</p></div>`).join("")}
function renderSetup(mode){const title=mode==="exam"?"Exam Mode":mode==="rapid"?"Rapid Fire":"Practice quiz",intro=mode==="exam"?"Take the full 100-question exam in randomized order, with all seven sections represented.":mode==="rapid"?"Fast, focused recall: answer each question and move straight on.":"Choose a format and build a focused practice set from the fixed 100-question bank.";pageContent.innerHTML=`<div class="eyebrow">ACTIVE RECALL</div><h1 class="page-title">${title}</h1><p class="subtitle">${intro}</p>${mode==="exam"?`<div class="toolbar"><span class="small">7 parts · 100 unique questions · randomized order</span><span class="small">Timer begins when you start</span></div>`:""}<div class="two-col" style="margin-top:22px"><section class="setup-card"><h3>Make it your session</h3><p>Questions are selected from the master bank. No new questions are generated.</p><label class="field-label" for="quiz-type">Quiz type</label><select id="quiz-type"><option value="all">${mode==="rapid"?"Rapid Fire · Mixed":"Mixed Quiz · All question types"}</option>${[["lines","Characters' Lines"],["oxymorons","Oxymoronic Expressions"],["identification","Identification"],["matching","Matching Type"],["analysis","Analysis"],["multiple","Multiple Choice"]].map(([v,l])=>`<option value="${v}">${l}</option>`).join("")}</select><label class="field-label" for="quiz-topic">Topic</label><select id="quiz-topic"><option value="all">All topics</option>${Object.entries(CATS).map(([k,v])=>`<option value="${k}">${v}</option>`).join("")}</select><label class="field-label" for="quiz-difficulty">Difficulty</label><select id="quiz-difficulty"><option>Any</option><option>Easy</option><option>Normal</option><option>Hard</option></select><label class="field-label">Number of questions</label><div class="choice-chips" id="count-chips">${(mode==="exam"?[100]:[5,10,20,50,100]).map((n,i)=>`<button class="chip ${i===0?"selected":""}" data-count="${n}">${n}</button>`).join("")}</div><div class="setup-actions"><button class="primary-btn" data-action="start-quiz" data-mode="${mode}">${mode==="exam"?"Begin exam":mode==="rapid"?"Start rapid fire":"Start quiz"} <span class="btn-arrow">→</span></button></div></section><section class="setup-card"><h3>Session guide</h3><p>One question at a time. After each answer, see the correct response and a short reason to help it stick.</p><div class="setting-row"><span>Question bank</span><b>100 fixed questions</b></div><div class="setting-row"><span>Questions already answered</span><b>${totalStats().done} / 100</b></div><div class="setting-row"><span>Saved for mistake review</span><b>${state.mistakes.length}</b></div><div class="setting-row"><span>Recent sessions</span><b>${state.scores.length}</b></div><p style="margin-top:18px">For a custom set, select one section or combine sections, then choose a question count.</p></section></div>`}
function getSelectedCount(){return Number(document.querySelector(".chip.selected")?.dataset.count||5)}
function startQuiz(mode,onlyMistakes=false,topicOverride=null){
 const topic=topicOverride||document.getElementById("quiz-topic")?.value||"all",type=document.getElementById("quiz-type")?.value||"all",difficulty=document.getElementById("quiz-difficulty")?.value||"Any";
 let pool=onlyMistakes?qbank.filter(q=>state.mistakes.some(m=>m.id===q.id)):qbank.filter(q=>(topic==="all"||categoryFor(q)===topic)&&(difficulty==="Any"||q.difficulty===difficulty)&&typeMatches(q,type));
 if(!pool.length){toast("No saved questions fit those choices yet.");return}
 const count=mode==="exam"?100:onlyMistakes?pool.length:Math.min(getSelectedCount(),pool.length),matching=type==="matching"&&!onlyMistakes&&mode!=="exam";
 let matchingRounds=[];
 if(matching){const candidates=shuffled(pool).slice(0,count);for(let i=0;i<candidates.length;i+=5)matchingRounds.push(candidates.slice(i,i+5))}
 const picked=matching?matchingRounds.flat():count===pool.length?pool:shuffled(pool).slice(0,count);
 quiz={items:matching?picked:mode==="exam"?shuffled(qbank):shuffled(picked),matching,matchingRounds,round:0,responseSets:[],index:0,answers:[],selected:null,checked:false,mode,started:Date.now(),onlyMistakes,label:matching?"Matching Type - Greek Gods":onlyMistakes?"Mistake review":mode==="exam"?"Full exam":mode==="rapid"?"Rapid Fire":topic==="all"?"Practice quiz":CATS[topic]};
 renderQuiz()
}
function typeMatches(q,t){if(t==="all")return true;if(t==="lines")return categoryFor(q)==="lines";if(t==="oxymorons")return categoryFor(q)==="oxymorons";if(t==="identification")return ["stories","history"].includes(categoryFor(q));if(t==="matching")return categoryFor(q)==="gods";if(t==="analysis")return categoryFor(q)==="qualities";if(t==="multiple")return categoryFor(q)==="works";return true}
function renderQuiz(){if(!quiz)return;if(quiz.matching){renderMatchingQuiz();return}const q=quiz.items[quiz.index];if(!q){finishQuiz();return}const n=quiz.index+1,total=quiz.items.length,done=quiz.checked,selected=quiz.selected,correct=selected===q.answer,cat=categoryFor(q);const response=q.choices?`<div class="options">${q.choices.map((ch,i)=>{let cls="option";if(done&&ch===q.answer)cls+=" correct";else if(done&&ch===selected)cls+=" wrong";else if(ch===selected)cls+=" selected";return `<button class="${cls}" ${done?"disabled":""} data-action="answer" data-answer="${esc(ch)}"><span class="option-key">${String.fromCharCode(65+i)}</span><span>${esc(ch)}</span></button>`}).join("")}</div>`:`<textarea class="answer-input" id="short-answer" placeholder="${q.kind==="Identification"||q.kind==="Written Answer"?"Type your answer here...":"Write a short answer..."}" ${done?"disabled":""}>${selected?esc(selected):""}</textarea>`;pageContent.innerHTML=`<div class="quiz-wrap"><div class="quiz-meta"><span>${esc(quiz.label)}${quiz.mode==="exam"?` | ${formatTime(Date.now()-quiz.started)}`:""}</span><span>Question ${n} of ${total}</span></div><div class="quiz-progress"><div style="width:${(n-1+(done?1:0))/total*100}%"></div></div><div class="question-card"><span class="q-tag">${esc(q.topic)} | ${esc(q.kind)}</span><div class="question-text">${esc(q.prompt)}</div>${response}${done?`<div class="feedback ${correct?"good":"bad"}"><b>${correct?"Correct!":"Not quite."} ${correct?"":"Correct answer: "+esc(q.answer)}</b>${esc(q.explanation)}</div>`:""}<div class="quiz-controls"><span class="muted-note">${done?`Difficulty: ${q.difficulty}`:"Think it through, then choose an answer."}</span>${done?`<button class="primary-btn" data-action="next-question">${n===total?"See results":"Next question"} </button>`:q.choices?`<span class="small">Select an answer to check it</span>`:`<button class="primary-btn" data-action="check-text">Check answer</button>`}</div></div><button class="text-link" style="margin-top:16px" data-action="exit-quiz">Leave session</button></div>`}
function renderMatchingQuiz(){const round=quiz.matchingRounds[quiz.round];if(!round){finishQuiz();return}const total=quiz.items.length,first=quiz.index+1,last=quiz.index+round.length,done=quiz.checked;quiz.responseSets[quiz.round]??=shuffled(round.map(q=>q.answer));const responses=quiz.responseSets[quiz.round];const rows=round.map((q,i)=>{const result=quiz.answers[quiz.index+i],letter=result?responses.indexOf(result.answer):-1,feedback=done?result.correct?`<div class="match-feedback correct">Correct. ${esc(q.explanation)}</div>`:`<div class="match-feedback wrong">Correct response: ${esc(q.answer)}. ${esc(q.explanation)}</div>`:"";return `<div class="matching-row ${done?(result.correct?"is-correct":"is-wrong"):""}"><div class="matching-premise"><span class="match-number">${String(quiz.index+i+1).padStart(2,"0")}</span><span>${esc(q.prompt)}</span></div><select id="match-${q.id}" aria-label="Choose the matching response for item ${quiz.index+i+1}" ${done?"disabled":""}><option value="">Choose a response</option>${responses.map((answer,j)=>`<option value="${j}" ${letter===j?"selected":""}>${String.fromCharCode(65+j)}. ${esc(answer)}</option>`).join("")}</select>${feedback}</div>`}).join("");pageContent.innerHTML=`<div class="quiz-wrap matching-quiz"><div class="quiz-meta"><span>${esc(quiz.label)}</span><span>Questions ${first}-${last} of ${total}</span></div><div class="quiz-progress"><div style="width:${(done?last:quiz.index)/total*100}%"></div></div><div class="question-card"><span class="q-tag">Greek Gods &amp; Goddesses | Matching Type</span><p class="matching-instructions">Match each premise in Column A with a response in Column B. Choose a letter for every row, then check your matches.</p><div class="matching-columns"><section class="matching-column"><header><span>Column A</span><small>PREMISES</small></header>${rows}</section><section class="matching-column response-column"><header><span>Column B</span><small>RESPONSES</small></header><ol class="matching-responses">${responses.map((answer,i)=>`<li><span>${String.fromCharCode(65+i)}</span><div>${esc(answer)}</div></li>`).join("")}</ol></section></div><div class="quiz-controls"><span class="muted-note">${done?"Review the matches and explanations above.":"Each response is used once."}</span>${done?`<button class="primary-btn" data-action="next-matching">${quiz.index+round.length>=total?"See results":"Next set"} </button>`:`<button class="primary-btn" data-action="check-matching">Check matches</button>`}</div></div><button class="text-link" style="margin-top:16px" data-action="exit-quiz">Leave session</button></div>`}
function checkMatching(){if(!quiz||quiz.checked)return;const round=quiz.matchingRounds[quiz.round],responses=quiz.responseSets[quiz.round];round.forEach((q,i)=>{const choice=document.getElementById(`match-${q.id}`)?.value,answer=choice===""||choice==null?"(No response selected)":responses[Number(choice)],correct=answer===q.answer;quiz.answers[quiz.index+i]={id:q.id,answer,correct};state.answered[q.id]=correct;state.mistakes=state.mistakes.filter(m=>m.id!==q.id);if(!correct)state.mistakes.push({id:q.id,answer,at:Date.now()})});quiz.checked=true;const today=new Date().toISOString().slice(0,10);if(state.lastStudy!==today){state.streak=state.lastStudy&&((new Date(today)-new Date(state.lastStudy))/86400000===1)?(state.streak||0)+1:1;state.lastStudy=today}saveState();document.getElementById("streak-number").textContent=`${state.streak||0} day streak`;renderQuiz()}
function normalize(s){return String(s||"").trim().toLowerCase().replace(/[.,!?;:]/g,"").replace(/\s+/g," ")}
function checkAnswer(answer){if(!quiz||quiz.checked||answer==null||!String(answer).trim())return;const q=quiz.items[quiz.index],correct=normalize(answer)===normalize(q.answer);quiz.selected=answer;quiz.checked=true;quiz.answers[quiz.index]={id:q.id,answer,correct};state.answered[q.id]=correct;state.mistakes=state.mistakes.filter(m=>m.id!==q.id);if(!correct)state.mistakes.push({id:q.id,answer,at:Date.now()});const today=new Date().toISOString().slice(0,10);if(state.lastStudy!==today){state.streak=state.lastStudy&&((new Date(today)-new Date(state.lastStudy))/86400000===1)?(state.streak||0)+1:1;state.lastStudy=today}saveState();document.getElementById("streak-number").textContent=`${state.streak||0} day streak`;renderQuiz()}
function finishQuiz(){const answers=quiz.answers.filter(Boolean),right=answers.filter(a=>a.correct).length,total=answers.length,by={};answers.forEach(a=>{const q=qbank.find(x=>x.id===a.id),k=categoryFor(q);by[k]??={right:0,total:0};by[k].total++;if(a.correct)by[k].right++});const sorted=Object.entries(by).sort((a,b)=>a[1].right/a[1].total-b[1].right/b[1].total),weakest=sorted[0],strongest=sorted[sorted.length-1];const score={score:right,total,correct:right,wrong:total-right,date:new Date().toISOString(),label:quiz.label,by};state.scores.push(score);if(state.scores.length>30)state.scores=state.scores.slice(-30);saveState();quiz=null;pageContent.innerHTML=`<div class="quiz-wrap"><div class="question-card"><div class="result-hero"><div class="result-circle">${pct(right,total)}%</div><h2>${activePage==="exam"?"Exam complete":"Nice work — session complete"}</h2><p>${activePage==="exam"?"Your full-bank exam results are ready.":"Every question is another step toward exam day."}</p><div class="pattern" style="margin:15px auto"></div></div><div class="result-stats"><div class="result-stat"><b>${right}/${total}</b><span>FINAL SCORE</span></div><div class="result-stat"><b>${right}</b><span>CORRECT</span></div><div class="result-stat"><b>${total-right}</b><span>INCORRECT</span></div></div>${activePage==="exam"?`<div class="section-head"><h2>Performance by category</h2></div>`:""}${Object.entries(by).map(([k,v])=>`<div class="breakdown-row"><label>${CATS[k]}</label><span>${v.right}/${v.total} · ${pct(v.right,v.total)}%</span><div class="progress-track"><div class="progress-fill" style="width:${pct(v.right,v.total)}%"></div></div></div>`).join("")}${activePage==="exam"&&weakest?`<div class="setting-row"><span>Weakest category</span><b>${CATS[weakest[0]]}</b></div><div class="setting-row"><span>Strongest category</span><b>${CATS[strongest[0]]}</b></div>`:""}${weakest?`<div class="recommend" style="margin-top:17px"><span class="recommend-icon">◎</span><div><b>Recommended review: ${CATS[weakest[0]]}</b><p>${weakest[1].right} correct out of ${weakest[1].total} in this category. Review the questions you missed and try them again.</p></div></div>`:""}<div class="setup-actions" style="gap:9px"><button class="secondary-btn" data-page="dashboard">Back to dashboard</button><button class="primary-btn" data-page="mistakes">Review mistakes</button></div></div></div>`;document.getElementById("page-name").textContent="Results"}
function formatTime(ms){const n=Math.floor(ms/1000),m=String(Math.floor(n/60)).padStart(2,"0"),s=String(n%60).padStart(2,"0");return `${m}:${s}`}
function renderMistakes(){const rows=state.mistakes.map(m=>{const q=qbank.find(x=>x.id===m.id);if(!q)return"";return `<article class="mistake-row"><button class="secondary-btn mistake-action" data-action="practice-mistakes">Practice</button><h4>${esc(q.prompt)}</h4><div class="mistake-details"><strong>Your answer:</strong> ${esc(m.answer)}<br><strong>Correct answer:</strong> ${esc(q.answer)}<br><strong>Why:</strong> ${esc(q.explanation)}<br><strong>Topic:</strong> ${esc(q.category)} · ${esc(q.topic)} <span class="small">· ${esc(q.id)}</span></div></article>`}).join("");pageContent.innerHTML=`<div class="eyebrow">TURN MISSES INTO MOMENTUM</div><h1 class="page-title">Review my mistakes</h1><p class="subtitle">Questions you missed are saved here. Get them right in a later quiz and they leave your review list.</p><div class="panel" style="margin-top:20px">${state.mistakes.length?`<div class="section-head" style="margin-top:0"><h2>${state.mistakes.length} question${state.mistakes.length===1?"":"s"} to revisit</h2><button class="primary-btn" data-action="practice-mistakes">Practice my mistakes →</button></div>${rows}`:`<div class="empty-state"><div class="empty-icon">✓</div><h3>No mistakes saved</h3><p>When you miss a question, it will appear here with the right answer and a short explanation.</p><button class="primary-btn" data-page="practice">Start practicing</button></div>`}</div>`}
function renderProgress(){const s=totalStats(),rows=Object.entries(CATS).map(([k,title])=>{const p=performance()[k];return `<div class="breakdown-row"><label>${title}</label><span>${p.right}/${p.done} correct · ${p.done}/${p.total} practiced</span><div class="progress-track"><div class="progress-fill" style="width:${p.total?p.done/p.total*100:0}%"></div></div></div>`}).join("");pageContent.innerHTML=`<div class="eyebrow">YOUR LEARNING, AT A GLANCE</div><h1 class="page-title">Study progress</h1><p class="subtitle">Progress is saved on this device and updates as you answer questions.</p><div class="stats-grid" style="margin-top:21px"><div class="stat-card"><div class="stat-top">Total answered <span class="stat-icon">◉</span></div><div class="stat-value">${s.done}</div><div class="stat-foot">Unique questions practiced</div></div><div class="stat-card"><div class="stat-top">Correct <span class="stat-icon">✓</span></div><div class="stat-value">${s.right}</div><div class="stat-foot">Questions answered correctly</div></div><div class="stat-card"><div class="stat-top">Incorrect <span class="stat-icon">↻</span></div><div class="stat-value">${s.wrong}</div><div class="stat-foot">Revisit any time in mistakes</div></div><div class="stat-card"><div class="stat-top">Accuracy <span class="stat-icon">↗</span></div><div class="stat-value">${s.accuracy}%</div><div class="stat-foot">Across unique questions attempted</div></div></div><section class="panel"><h3>Progress by topic</h3>${rows}</section><section class="panel" style="margin-top:15px"><h3>Recent quiz scores</h3>${state.scores.length?state.scores.slice(-8).reverse().map(r=>`<div class="recent-row"><span>${esc(r.label)} · ${new Date(r.date).toLocaleString()}</span><span class="score-pill">${r.score}/${r.total} · ${pct(r.score,r.total)}%</span></div>`).join(""):`<div class="recent-empty">Finish a quiz to see your scores here.</div>`}</section>`}
function renderFlashcards(){const pool=flash.items.length?flash.items:qbank;const card=pool[flash.index%pool.length];if(!card){pageContent.innerHTML=`<div class="empty-state">No cards available.</div>`;return}const front=card.prompt,back=`${card.answer} — ${card.explanation}`;pageContent.innerHTML=`<div class="eyebrow">QUICK REVIEW · ACTIVE RECALL</div><h1 class="page-title">Flashcards</h1><p class="subtitle">Try to recall the answer before tapping to reveal.</p><div class="flash-wrap"><div class="flash-card" data-action="reveal-card"><span class="q-tag">${esc(card.topic)}</span>${flash.revealed?`<div class="flash-answer" style="margin-top:20px">${esc(back)}</div>`:`<div class="question-text">${esc(front)}</div><span class="small">Tap card to reveal answer</span>`}</div>${flash.revealed?`<div class="flash-actions"><button class="secondary-btn" data-action="card-again">✕ Need review</button><button class="primary-btn" data-action="card-know">✓ I know this</button></div>`:""}<div class="card-counter">Card ${flash.index+1} of ${pool.length} · <button class="text-link" data-action="shuffle-cards">Shuffle cards</button></div></div>`}
function renderSettings(){pageContent.innerHTML=`<div class="eyebrow">STUDY APP SETTINGS</div><h1 class="page-title">Settings</h1><p class="subtitle">No account needed. Your study progress stays in this browser, and you can reset it whenever you like.</p><div class="panel" style="margin-top:20px;max-width:680px"><h3>Appearance</h3><div class="setting-row"><span>Color theme</span><button class="secondary-btn" data-action="toggle-theme">Switch to ${state.settings?.theme==="dark"?"light":"dark"} mode</button></div></div><div class="panel" style="margin-top:15px;max-width:680px"><h3>Study data on this device</h3><div class="setting-row"><span>Saved questions answered</span><b>${Object.keys(state.answered).length} / 100</b></div><div class="setting-row"><span>Saved quiz sessions</span><b>${state.scores.length}</b></div><div class="setting-row"><span>Saved mistakes</span><b>${state.mistakes.length}</b></div><div style="margin-top:17px"><button class="secondary-btn" data-action="export-data">Download my study data</button> <button class="ghost-btn" data-action="reset-data">Reset all progress</button></div><p style="margin:15px 0 0;font-size:10px;color:#94979a">Reset clears saved answers, scores, mistakes, flashcard status, and streak from this browser.</p></div>`}
function toast(msg){const el=document.getElementById("toast");el.textContent=msg;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),2200)}

document.addEventListener("click",e=>{const target=e.target.closest("button,[data-action],[data-topic]");if(!target)return;if(target.dataset.page){e.preventDefault();quiz=null;setPage(target.dataset.page);return}if(target.dataset.topic&&target.classList.contains("topic-card")){activePage="practice";renderSetup("practice");setTimeout(()=>{const sel=document.getElementById("quiz-topic");if(sel)sel.value=target.dataset.topic},0);return}if(target.dataset.count){document.querySelectorAll(".chip").forEach(c=>c.classList.toggle("selected",c===target));return}const action=target.dataset.action;if(!action)return;switch(action){case"toggle-theme":toggleTheme();break;case"start-quiz":startQuiz(target.dataset.mode);break;case"answer":checkAnswer(target.dataset.answer);break;case"check-text":checkAnswer(document.getElementById("short-answer")?.value);break;case"next-question":quiz.index++;quiz.selected=null;quiz.checked=false;renderQuiz();break;case"check-matching":checkMatching();break;case"next-matching":quiz.index+=quiz.matchingRounds[quiz.round].length;quiz.round++;quiz.checked=false;renderQuiz();break;case"exit-quiz":quiz=null;renderPage();break;case"practice-mistakes":if(!state.mistakes.length){toast("There are no saved mistakes yet.");break}startQuiz("practice",true);break;case"practice-topic":activePage="practice";renderSetup("practice");setTimeout(()=>{const sel=document.getElementById("quiz-topic");if(sel)sel.value=target.dataset.topic},0);break;case"reveal-card":flash.revealed=!flash.revealed;renderFlashcards();break;case"card-again":flash.revealed=false;flash.index=(flash.index+1)%flash.items.length;renderFlashcards();break;case"card-know":flash.revealed=false;state.flashcards[flash.items[flash.index].id]="known";saveState();flash.index=(flash.index+1)%flash.items.length;renderFlashcards();break;case"shuffle-cards":flash.items=shuffled(qbank);flash.index=0;flash.revealed=false;renderFlashcards();break;case"export-data":downloadData();break;case"reset-data":if(confirm("Clear all saved scores, mistakes, and progress from this browser?")){const theme=state.settings?.theme;state=freshState();if(theme)state.settings.theme=theme;saveState();renderPage();toast("Study progress cleared.")}break}});
document.getElementById("mobile-menu").addEventListener("click",()=>document.getElementById("sidebar").classList.toggle("open"));
document.addEventListener("keydown",e=>{if(e.key==="Enter"&&e.target.id==="short-answer"&&!e.shiftKey){e.preventDefault();document.querySelector('[data-action="check-text"]')?.click()}});
function downloadData(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),questionBank:qbank.map(({id,category,topic,prompt,kind,choices,answer,explanation,difficulty})=>({id,category,topic,question:prompt,questionType:kind,choices,correctAnswer:answer,explanation,difficulty})),progress:state},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="greeklit-study-data.json";a.click();URL.revokeObjectURL(a.href)}
function validateBank(){const counts={};qbank.forEach(q=>{const k=categoryFor(q);counts[k]=(counts[k]||0)+1});const ids=new Set(qbank.map(q=>q.id));if(qbank.length!==100||Object.keys(EXPECTED).some(k=>counts[k]!==EXPECTED[k])||ids.size!==100)console.error("Question bank validation failed",qbank.length,counts,ids.size);else console.info("Question bank verified: exactly 100 unique questions",counts)}
validateBank();applyTheme();updateMistakeBadge();document.getElementById("streak-number").textContent=`${state.streak||0} day streak`;setPage("dashboard");
